import { workflow, node, trigger, sticky, expr, newCredential, ifElse, switchCase, languageModel, memory } from '@n8n/workflow-sdk';

const openPage = trigger({ type: 'n8n-nodes-base.webhook', version: 2.1, config: { name: 'Open Y Square', parameters: { httpMethod: 'GET', path: "Y2Workplace", responseMode: 'responseNode' }, position: [0, 0] }, output: [{ headers: {}, query: {}, body: {} }] });
const loadPage = node({ type: 'n8n-nodes-base.postgres', version: 2.6, config: { name: 'Load Page', parameters: { operation: 'executeQuery', query: "SELECT html FROM ys_ui_pages WHERE page = 'ysquare'", options: {} }, credentials: { postgres: newCredential('Y Square Postgres') }, alwaysOutputData: true, onError: 'continueRegularOutput', position: [224, 0] }, output: [{ html: '<!DOCTYPE html><html>...</html>' }] });
const preparePage = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: 'Prepare Page', parameters: { mode: 'runOnceForAllItems', language: 'javaScript', jsCode: "const first = $input.all()[0];\nconst row = first ? first.json : {};\nconst deployed = row && typeof row.html === 'string' && row.html.length > 100;\nconst fallback = '<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><title>Y Square Workplace</title></head><body style=\"font-family:Inter,Segoe UI,sans-serif;padding:48px;color:#0d1220\"><h1>Y Square UI is not deployed yet</h1><p>The page is served from the ys_ui_pages table. Run <code>npm run deploy:ui</code> from the ysquare project with YSQUARE_DEPLOY_KEY set to publish it.</p></body></html>';\nreturn [{ json: { html: deployed ? row.html : fallback } }];" }, position: [448, 0] }, output: [{ html: '<!DOCTYPE html><html>...</html>' }] });
const servePage = node({ type: 'n8n-nodes-base.respondToWebhook', version: 1.5, config: { name: 'Serve Y Square App', parameters: { respondWith: 'text', responseBody: expr('{{ $json.html }}'), options: { responseHeaders: { entries: [{ name: 'Content-Type', value: 'text/html; charset=utf-8' }, { name: 'Cache-Control', value: 'no-store' }, { name: 'X-Content-Type-Options', value: 'nosniff' }] } } }, position: [672, 0] }, output: [{}] });
const deployRequest = trigger({ type: 'n8n-nodes-base.webhook', version: 2.1, config: { name: 'Deploy Request', parameters: { httpMethod: 'POST', path: "Y2Workplace/deploy-ui", responseMode: 'responseNode' }, position: [0, 260] }, output: [{ headers: { 'x-deploy-key': 'secret' }, body: { page: 'ysquare', html: '<!DOCTYPE html>...' } }] });
const hashDeployKey = node({ type: 'n8n-nodes-base.crypto', version: 2, config: { name: 'Hash Deploy Key', parameters: { action: 'hash', type: 'SHA256', value: expr("{{ String((($json.headers || {})['x-deploy-key']) || '') }}"), dataPropertyName: 'keyHash', encoding: 'hex' }, position: [224, 260] }, output: [{ keyHash: 'abc', body: { page: 'ysquare', html: '...' } }] });
const checkDeployKey = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: 'Check Deploy Key', parameters: { mode: 'runOnceForAllItems', language: 'javaScript', jsCode: "// Only the SHA-256 of the deploy key is stored here; the key itself stays with the deployer (workflows/deploy_ui.js).\nconst KEY_HASH = \"782ac9a78df7cdcbbaf0727a1f3006e33ecc3fecb327d5dc3b35aa9c28623a0c\";\nconst it = $input.first().json;\nconst body = it.body || {};\nconst ok = typeof it.keyHash === 'string' && it.keyHash.length === 64 && it.keyHash === KEY_HASH;\nif (!ok) return [{ json: { denied: true, status: 401, sql: 'SELECT 0 AS bytes', params: [], response: { success: false, error: { code: 'UNAUTHORIZED', message: 'Invalid deploy key.' } } } }];\nconst page = String(body.page || 'ysquare');\nconst html = typeof body.html === 'string' ? body.html : '';\nif (!/^[a-z0-9-]{1,40}$/.test(page) || html.length < 100 || html.length > 4000000) return [{ json: { denied: true, status: 400, sql: 'SELECT 0 AS bytes', params: [], response: { success: false, error: { code: 'BAD_REQUEST', message: 'Body must contain page (slug) and html (100 chars to 4 MB).' } } } }];\nreturn [{ json: { denied: false, status: 200, page, sql: 'INSERT INTO ys_ui_pages (page, html, updated_at, updated_by) VALUES ($1, $2, now(), $3) ON CONFLICT (page) DO UPDATE SET html = EXCLUDED.html, updated_at = now(), updated_by = EXCLUDED.updated_by RETURNING page, length(html) AS bytes, updated_at', params: [page, html, String(body.by || 'deploy_ui.js')], response: null } }];" }, position: [448, 260] }, output: [{ denied: false, status: 200, page: 'ysquare', sql: 'INSERT ...', params: [] }] });
const ensureTable = node({ type: 'n8n-nodes-base.postgres', version: 2.6, config: { name: 'Ensure Table', parameters: { operation: 'executeQuery', query: 'CREATE TABLE IF NOT EXISTS ys_ui_pages (page text PRIMARY KEY, html text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), updated_by text)', options: {} }, credentials: { postgres: newCredential('Y Square Postgres') }, alwaysOutputData: true, onError: 'continueRegularOutput', position: [672, 260] }, output: [{}] });
const savePage = node({ type: 'n8n-nodes-base.postgres', version: 2.6, config: { name: 'Save Page', parameters: { operation: 'executeQuery', query: expr("{{ $('Check Deploy Key').first().json.sql }}"), options: { queryReplacement: expr("{{ $('Check Deploy Key').first().json.params }}") } }, credentials: { postgres: newCredential('Y Square Postgres') }, alwaysOutputData: true, onError: 'continueRegularOutput', position: [896, 260] }, output: [{ page: 'ysquare', bytes: 120000, updated_at: '2026-01-01T00:00:00Z' }] });
const deployResult = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: 'Deploy Result', parameters: { mode: 'runOnceForAllItems', language: 'javaScript', jsCode: "const chk = $('Check Deploy Key').first().json;\nif (chk.denied) return [{ json: { status: chk.status, body: chk.response } }];\nconst first = $input.all()[0];\nconst row = first ? first.json : {};\nif (row.error || !row.page) return [{ json: { status: 500, body: { success: false, error: { code: 'DB_ERROR', message: String((row.error && row.error.message) || row.error || 'Save failed') } } } }];\nreturn [{ json: { status: 200, body: { success: true, data: { page: row.page, bytes: Number(row.bytes), updatedAt: row.updated_at } } } }];" }, position: [1120, 260] }, output: [{ status: 200, body: { success: true } }] });
const deployResponse = node({ type: 'n8n-nodes-base.respondToWebhook', version: 1.5, config: { name: 'Deploy Response', parameters: { respondWith: 'json', responseBody: expr('{{ $json.body }}'), options: { responseCode: expr('{{ $json.status }}') } }, position: [1344, 260] }, output: [{}] });
const note = sticky("## Y Square UI\nGET /webhook/Y2Workplace serves the Y Square Workplace single-page app (vanilla JS, no build step, same pattern as Neon Logistics UI). The HTML is read from the ys_ui_pages table so the page never has to live inside the workflow.\n\nPOST /webhook/Y2Workplace/deploy-ui with header X-Deploy-Key upserts a new page version. Only the SHA-256 of the key is stored in Check Deploy Key; the key stays with the deployer (npm run deploy:ui in the ysquare project).\n\nAll app data comes from Y Square Services (/svc/api) and Y Square Agents (/svc/chat). Guests are identified by an X-Guest-Id header, members by a bearer token.\n\nSource of truth for the page: ysquare/ui/*, assembled by workflows/gen_ui.js.", [ensureTable, savePage], { color: 4 });
export default workflow('ysquare-ui', 'Y Square UI')
  .add(openPage).to(loadPage).to(preparePage).to(servePage)
  .add(deployRequest).to(hashDeployKey).to(checkDeployKey).to(ensureTable).to(savePage).to(deployResult).to(deployResponse);
